  "inlineSchema": "// 설계도 시작\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  // 애플리케이션(lib/db.js)과 같은 환경변수를 쓴다.\n  // DB 를 옮길 때 DATABASE_URL 하나만 바꾸면 앱과 Prisma CLI 가 함께 따라간다.\n  url      = env(\"DATABASE_URL\")\n}\n\n// ⚠️ 주의: 아래 모델은 실제 DB 의 일부만 반영하고 있다.\n// 운영 DB 에는 concert, karaoke_number, questions, difficulty, quiz_ranking,\n// notice, goods, waiting_group, discord_channels, site_config, AdminUsers,\n// SuggestedQuestions, pending_karaoke 등의 테이블이 더 있다.\n// 서버컴 이전 전에 `npm run db:pull` 로 스키마를 실제 DB 와 동기화할 것.\n// (자세한 절차는 docs/DB-MIGRATION.md 참고)\n\n// 방명록 테이블 구조\nmodel messages {\n  id         Int      @id @default(autoincrement())\n  name       String\n  content    String\n  created_at DateTime @default(now())\n}\n\n// 티켓팅 연습 기록 테이블\nmodel ticketing_practice {\n  id        Int    @id @default(autoincrement())\n  name      String\n  stopwatch Int\n}\n\n// ─────────────────────────────────────────────────────\n// 개인 서버 관리용 중앙 API (Home Server Agent 연동 기반)\n// ─────────────────────────────────────────────────────\n\nenum ProjectStatus {\n  running\n  stopped\n  starting\n  stopping\n  restarting\n  error\n  unknown\n}\n\nenum CommandAction {\n  start\n  stop\n  restart\n}\n\nenum CommandStatus {\n  pending\n  processing\n  success\n  failed\n  cancelled\n}\n\nenum CommandSource {\n  web\n  discord\n  system\n}\n\nenum AgentStatus {\n  online\n  offline\n  unknown\n}\n\nenum LogLevel {\n  info\n  warn\n  error\n}\n\n// 서버컴에서 실행되는 Agent (현재는 등록/조회용, 실제 연결은 추후 구현)\nmodel Agent {\n  id         String      @id @default(cuid())\n  name       String      @unique\n  status     AgentStatus @default(unknown)\n  lastSeenAt DateTime?\n  createdAt  DateTime    @default(now())\n  updatedAt  DateTime    @updatedAt\n\n  projects Project[]\n\n  @@map(\"agents\")\n}\n\n// 관리 대상 프로젝트 (웹사이트/디스코드 봇/워커 등)\nmodel Project {\n  id          String        @id\n  name        String\n  description String?\n  status      ProjectStatus @default(unknown)\n  port        Int?\n  // 'web' | 'discord-bot' | 'worker' | 'api' | 'other' 등 (server/types/enums.js 참고)\n  type        String\n  // 추후 PM2/Docker 제어 시 사용할 \"내부 프로세스 이름\".\n  // 클라이언트가 임의로 넘길 수 없고 항상 DB에 등록된 값만 사용한다.\n  processName String?\n\n  agentId String?\n  agent   Agent?  @relation(fields: [agentId], references: [id])\n\n  createdAt  DateTime  @default(now())\n  updatedAt  DateTime  @updatedAt\n  lastSeenAt DateTime?\n\n  commands Command[]\n\n  @@index([agentId])\n  @@map(\"projects\")\n}\n\n// Web/Discord에서 생성되고, 나중에 Home Server Agent가 처리하는 제어 명령\nmodel Command {\n  id     String        @id @default(cuid())\n  action CommandAction\n  status CommandStatus @default(pending)\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id])\n\n  // 명령을 요청한 주체(관리자 아이디 / discord 사용자 등). 시스템 발행 명령은 null일 수 있다.\n  requestedBy String?\n  source      CommandSource\n\n  createdAt    DateTime  @default(now())\n  startedAt    DateTime?\n  finishedAt   DateTime?\n  errorMessage String?\n\n  logs CommandLog[]\n\n  @@index([projectId])\n  @@index([status])\n  @@map(\"commands\")\n}\n\n// Command 상태 변화 / 처리 결과 로그\nmodel CommandLog {\n  id        String   @id @default(cuid())\n  commandId String\n  command   Command  @relation(fields: [commandId], references: [id])\n  level     LogLevel @default(info)\n  message   String\n  createdAt DateTime @default(now())\n\n  @@index([commandId])\n  @@map(\"command_logs\")\n}\n",
